CREATE OR REPLACE FUNCTION public.axen_completion_reward_config() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT jsonb_build_object('zen_limit',1,'contract_limit',1,'wake_limit',1,'zen',10,'contract',10,'top3',10); $$;
CREATE OR REPLACE FUNCTION public.axen_award_completion_coins(_uid uuid,_source text,_id uuid,_slot smallint DEFAULT NULL) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE d date; z text; co integer; k text; cfg jsonb:=public.axen_completion_reward_config(); claims jsonb; e public.alarm_events; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(_uid::text,74010)); PERFORM 1 FROM public.profiles WHERE id=_uid FOR UPDATE; SELECT reward_timezone INTO z FROM public.profiles WHERE id=_uid; d:=public.axen_reward_local_day(_uid); IF _source NOT IN ('zen','contract','top3','wake') OR _id IS NULL THEN RAISE EXCEPTION 'invalid source'; END IF; IF _source='top3' AND (_slot IS NULL OR _slot NOT BETWEEN 1 AND 3) THEN RAISE EXCEPTION 'invalid slot'; END IF; IF _source='wake' THEN SELECT * INTO e FROM public.alarm_events WHERE id=_id AND user_id=_uid FOR UPDATE; IF e.status<>'solved' OR e.is_test OR e.tier=0 OR e.first_ring_at-e.saved_at<interval '2 hours' OR e.solved_at-e.first_ring_at>interval '30 minutes' THEN RETURN 0; END IF; IF EXISTS(SELECT 1 FROM public.coin_transactions WHERE user_id=_uid AND amount>0 AND (reward_source='wake' OR (reward_source IS NULL AND reason='wake')) AND (created_at AT TIME ZONE z)::date=d) THEN RETURN 0; END IF; co:=e.tier; ELSE claims:=public.get_daily_coin_rewards(); IF (_source='zen' AND (claims->>'zen_claimed')::boolean AND (cfg->>'zen_limit')::integer=1) OR (_source='contract' AND (claims->>'contract_claimed')::boolean AND (cfg->>'contract_limit')::integer=1) THEN RETURN 0; END IF; co:=(cfg->>_source)::integer; END IF; k:=CASE WHEN _source='top3' THEN _slot::text ELSE 'daily' END; PERFORM set_config('app.economy_write','on',true); PERFORM set_config('axen.contract_write','on',true); INSERT INTO public.coin_transactions(user_id,amount,reason,ref_id,reward_source,reward_local_date,reward_key,reward_timezone) VALUES(_uid,co,CASE _source WHEN 'contract' THEN 'contract_reward' ELSE _source END,_id,_source,d,k,z) ON CONFLICT DO NOTHING; IF NOT FOUND THEN RETURN 0; END IF; UPDATE public.profiles SET coins=coins+co WHERE id=_uid; RETURN co; END; $$;
CREATE OR REPLACE FUNCTION public.wake_submit_answer(_event_id uuid,_version integer,_answer text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u uuid:=auth.uid(); e public.alarm_events; a public.alarms; correct boolean; needed integer; awarded integer:=0; result text; day date; inserted boolean; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE='42501'; END IF; IF length(_answer)>40 THEN RAISE EXCEPTION 'invalid answer'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(u::text,74010)); PERFORM pg_advisory_xact_lock(hashtextextended(u::text,74011)); SELECT * INTO e FROM public.alarm_events WHERE id=_event_id AND user_id=u FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'alarm not found' USING ERRCODE='42501'; END IF; IF e.status='solved' THEN RETURN jsonb_build_object('solved',true,'correct',true,'awarded',0,'result','daily_claimed','event',public.wake_event_payload(e.id)); END IF; IF e.status<>'ringing' OR e.question_version<>_version THEN RAISE EXCEPTION 'Challenge changed. Reload the current question.'; END IF; IF e.last_answer_at>now()-interval '400 milliseconds' THEN RAISE EXCEPTION 'Please wait before another answer'; END IF; correct:=CASE WHEN e.question_type='science' THEN trim(_answer)=e.question_answer WHEN trim(_answer)~'^-?[0-9]+(\.[0-9]+)?$' THEN trim(_answer)::numeric=e.question_answer::numeric ELSE false END; needed:=CASE WHEN e.question_type='science' THEN 2 ELSE 1 END; UPDATE public.alarm_events SET correct_in_row=CASE WHEN correct THEN correct_in_row+1 ELSE 0 END,last_answer_at=now() WHERE id=e.id; IF NOT correct OR e.correct_in_row+1<needed THEN PERFORM public.wake_issue_question(e.id); RETURN jsonb_build_object('solved',false,'correct',correct,'explanation',CASE WHEN correct THEN e.question_explanation ELSE NULL END,'event',public.wake_event_payload(e.id)); END IF; UPDATE public.alarm_events SET status='solved',solved_at=now(),next_push_at=NULL WHERE id=e.id; result:=CASE WHEN e.is_test THEN 'test_alarm' WHEN e.tier=0 THEN 'outside_reward_window' WHEN e.first_ring_at-e.saved_at<interval '2 hours' THEN 'saved_too_late' WHEN now()-e.first_ring_at>interval '30 minutes' THEN 'solve_too_late' ELSE 'eligible' END; IF result='eligible' THEN awarded:=public.axen_award_completion_coins(u,'wake',e.id); result:=CASE WHEN awarded>0 THEN 'awarded' ELSE 'daily_claimed' END; END IF; SELECT * INTO a FROM public.alarms WHERE id=e.alarm_id FOR UPDATE; day:=public.axen_reward_local_day(u); IF NOT e.is_test THEN PERFORM set_config('app.economy_write','on',true); PERFORM set_config('axen.contract_write','on',true); INSERT INTO public.alarm_sessions(user_id,alarm_id,completed_on,coins_awarded,status,checked_in_at) VALUES(u,a.id,day,awarded,'completed',now()) ON CONFLICT(user_id,alarm_id,completed_on) DO NOTHING; inserted:=FOUND; IF inserted THEN UPDATE public.profiles SET streak=CASE WHEN last_activity_date=day THEN streak WHEN last_activity_date=day-1 THEN streak+1 ELSE 1 END,longest_streak=greatest(longest_streak,CASE WHEN last_activity_date=day THEN streak WHEN last_activity_date=day-1 THEN streak+1 ELSE 1 END),last_activity_date=day WHERE id=u; INSERT INTO public.task_completions(user_id,task_id,completed_on,coins_awarded) SELECT u,id,day,0 FROM public.tasks WHERE user_id=u AND is_active AND name~*'wake' ON CONFLICT(user_id,task_id,completed_on) DO NOTHING; END IF; IF a.wake_repeat_daily AND a.is_active THEN UPDATE public.alarms SET wake_next_fire_at=public.wake_next_fire(a.time,a.wake_timezone) WHERE id=a.id; PERFORM public.wake_create_occurrence(a.id); ELSE UPDATE public.alarms SET wake_next_fire_at=NULL,is_active=false WHERE id=a.id; END IF; END IF; UPDATE public.alarm_events SET coins_awarded=awarded,reward_result=result WHERE id=e.id; UPDATE public.wake_push_outbox SET status='cancelled' WHERE event_id=e.id AND status IN ('pending','leased'); INSERT INTO public.wake_delivery_log(event_id,kind) VALUES(e.id,'solved'); RETURN jsonb_build_object('solved',true,'correct',true,'awarded',awarded,'result',result,'explanation',e.question_explanation,'event',public.wake_event_payload(e.id)); END; $$;
CREATE OR REPLACE FUNCTION public.wake_subscribe(_endpoint text,_p256dh text,_auth text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u uuid:=auth.uid(); BEGIN IF u IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF; IF length(_endpoint)>2048 OR _endpoint!~'^https://' OR length(_p256dh)>256 OR length(_auth)>128 THEN RAISE EXCEPTION 'invalid subscription'; END IF; IF (SELECT count(*) FROM public.wake_push_subscriptions WHERE user_id=u)>=10 AND NOT EXISTS(SELECT 1 FROM public.wake_push_subscriptions WHERE endpoint=_endpoint AND user_id=u) THEN RAISE EXCEPTION 'subscription limit'; END IF; INSERT INTO public.wake_push_subscriptions(user_id,endpoint,p256dh,auth_key) VALUES(u,_endpoint,_p256dh,_auth) ON CONFLICT(endpoint) DO UPDATE SET user_id=u,p256dh=_p256dh,auth_key=_auth; END; $$;
CREATE OR REPLACE FUNCTION public.wake_sweep_due(_limit integer DEFAULT 500) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE e public.alarm_events; n integer:=0; BEGIN FOR e IN SELECT * FROM public.alarm_events WHERE status='scheduled' AND scheduled_for<=now() ORDER BY scheduled_for LIMIT least(greatest(_limit,1),500) FOR UPDATE SKIP LOCKED LOOP UPDATE public.alarm_events SET status='ringing',first_ring_at=now(),next_push_at=now() WHERE id=e.id; INSERT INTO public.wake_delivery_log(event_id,kind) VALUES(e.id,'ringing'); n:=n+1; END LOOP; FOR e IN SELECT * FROM public.alarm_events WHERE status='ringing' AND push_round<30 AND next_push_at<=now() ORDER BY next_push_at LIMIT 500 FOR UPDATE SKIP LOCKED LOOP INSERT INTO public.wake_push_outbox(event_id,subscription_id,round) SELECT e.id,id,e.push_round+1 FROM public.wake_push_subscriptions WHERE user_id=e.user_id ON CONFLICT DO NOTHING; UPDATE public.alarm_events SET push_round=push_round+1,next_push_at=now()+interval '60 seconds' WHERE id=e.id; END LOOP; RETURN n; END; $$;
CREATE OR REPLACE FUNCTION public.wake_claim_push(_limit integer DEFAULT 6) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE rows jsonb; BEGIN WITH due AS (SELECT o.id FROM public.wake_push_outbox o JOIN public.alarm_events e ON e.id=o.event_id WHERE e.status='ringing' AND ((o.status='pending' AND o.retry_at<=now()) OR (o.status='leased' AND o.lease_until<now())) AND o.attempts<6 ORDER BY o.retry_at LIMIT least(greatest(_limit,1),6) FOR UPDATE OF o SKIP LOCKED), claimed AS (UPDATE public.wake_push_outbox o SET status='leased',lease_token=gen_random_uuid(),lease_until=now()+interval '30 seconds',attempts=attempts+1 FROM due WHERE o.id=due.id RETURNING o.*) SELECT jsonb_agg(jsonb_build_object('id',c.id,'event_id',c.event_id,'round',c.round,'lease_token',c.lease_token,'subscription_id',s.id,'endpoint',s.endpoint,'p256dh',s.p256dh,'auth',s.auth_key)) INTO rows FROM claimed c JOIN public.wake_push_subscriptions s ON s.id=c.subscription_id; RETURN coalesce(rows,'[]'::jsonb); END; $$;
CREATE OR REPLACE FUNCTION public.wake_finish_push(_id uuid,_lease uuid,_http integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE o public.wake_push_outbox; BEGIN SELECT * INTO o FROM public.wake_push_outbox WHERE id=_id AND lease_token=_lease AND status='leased' FOR UPDATE; IF NOT FOUND THEN RETURN; END IF; IF _http IN (404,410) THEN DELETE FROM public.wake_push_subscriptions WHERE id=o.subscription_id; RETURN; END IF; UPDATE public.wake_push_outbox SET status=CASE WHEN _http BETWEEN 200 AND 299 THEN 'accepted' WHEN attempts>=6 THEN 'failed' ELSE 'pending' END,accepted_at=CASE WHEN _http BETWEEN 200 AND 299 THEN now() END,retry_at=now()+make_interval(secs=>least(3600,(power(2,attempts)*10)::integer)),lease_until=NULL,last_error=CASE WHEN _http BETWEEN 200 AND 299 THEN NULL ELSE _http::text END WHERE id=o.id; INSERT INTO public.wake_delivery_log(event_id,kind,detail) VALUES(o.event_id,CASE WHEN _http BETWEEN 200 AND 299 THEN 'accepted' ELSE 'push_failed' END,_http::text); END; $$;
CREATE OR REPLACE FUNCTION public.guard_wake_alarm_fields() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF current_user IN ('authenticated','anon') AND NEW.label='AXEN Wake Protocol' AND NEW.wake_saved_at IS NOT NULL THEN IF TG_OP='INSERT' THEN RAISE EXCEPTION 'Use wake settings'; END IF; NEW.wake_next_fire_at:=OLD.wake_next_fire_at;NEW.wake_saved_at:=OLD.wake_saved_at;NEW.wake_timezone:=OLD.wake_timezone;NEW.time:=OLD.time;NEW.is_active:=OLD.is_active;NEW.challenge_type:=OLD.challenge_type;NEW.tone:=OLD.tone; END IF; RETURN NEW; END; $$;
CREATE TRIGGER wake_alarm_server_fields BEFORE INSERT OR UPDATE ON public.alarms FOR EACH ROW EXECUTE FUNCTION public.guard_wake_alarm_fields();
CREATE OR REPLACE FUNCTION public.wake_timezone_reschedule() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a public.alarms; BEGIN IF NEW.reward_timezone IS DISTINCT FROM OLD.reward_timezone THEN FOR a IN SELECT * FROM public.alarms WHERE user_id=NEW.id AND label='AXEN Wake Protocol' AND is_active AND wake_saved_at IS NOT NULL FOR UPDATE LOOP UPDATE public.alarm_events SET status='expired' WHERE alarm_id=a.id AND status='scheduled' AND NOT is_test; UPDATE public.alarms SET wake_timezone=NEW.reward_timezone,wake_saved_at=now(),wake_next_fire_at=public.wake_next_fire(a.time,NEW.reward_timezone) WHERE id=a.id; PERFORM public.wake_create_occurrence(a.id); END LOOP; END IF; RETURN NEW; END; $$;
CREATE TRIGGER wake_timezone_changed AFTER UPDATE OF reward_timezone ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.wake_timezone_reschedule();
REVOKE ALL ON FUNCTION public.wake_submit_answer(uuid,integer,text),public.wake_subscribe(text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.wake_submit_answer(uuid,integer,text),public.wake_subscribe(text,text,text) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.wake_sweep_due(integer),public.wake_claim_push(integer),public.wake_finish_push(uuid,uuid,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.wake_sweep_due(integer),public.wake_claim_push(integer),public.wake_finish_push(uuid,uuid,integer) TO service_role;
CREATE OR REPLACE VIEW public.wake_daily_monitor WITH(security_invoker=true) AS SELECT (occurred_at AT TIME ZONE 'UTC')::date AS day,kind,count(*) AS total FROM public.wake_delivery_log GROUP BY 1,2;
REVOKE ALL ON public.wake_daily_monitor FROM anon,authenticated;
GRANT SELECT ON public.wake_daily_monitor TO service_role;